class Solution {
public:
    int arrayPairSum(vector<int>& nums) {
        int count[20001] = {0};
        for (int x : nums) {
            count[x + 10000]++;
        }
        int sum = 0;
        bool take = true;
        for (int i = 0; i < 20001; ++i) {
            while (count[i] > 0) {
                if (take) {
                    sum += i - 10000;
                }
                take = !take;
                count[i]--;
            }
        }
        return sum;
    }
};
